INSERT INTO cf_recon.cf_image (image_id, uploaded_at, filename, meta, first_seen_at, last_seen_at) SELECT p.cloudflare_image_id, COALESCE(p.cf_uploaded_at, p.created_at), p.filename, jsonb_build_object('claude_recon', true, 'backfilled_at', now(), 'source', 'product_images_verified_no_audit'), now(), now() FROM public.product_images p WHERE p.deleted_at IS NULL AND p.cf_sync_status = 'verified' AND NOT EXISTS (SELECT 1 FROM cf_recon.cf_image c WHERE c.image_id = p.cloudflare_image_id) ON CONFLICT (image_id) DO NOTHING;;
